<?= $this->extend('layouts/main') ?><?= $this->section('content') ?><?php $edit=$product!==null; ?><div class="page-head"><h1><?= $edit?'Edit':'Add' ?> Product</h1></div><form class="panel form" method="post" enctype="multipart/form-data" action="<?= $edit?site_url('products/'.$product['id']):site_url('products') ?>"><?= csrf_field() ?><label>Name<input name="name" maxlength="100" value="<?= esc(old('name')??($product['name']??'')) ?>" required></label><label>Price<input type="number" name="price" min="0" step="0.01" value="<?= esc(old('price')??($product['price']??'')) ?>" required></label><label>Stock quantity<input type="number" name="stock_quantity" min="0" value="<?= esc(old('stock_quantity')??($product['stock_quantity']??0)) ?>" required></label><label>Product image<input type="file" name="image" accept="image/png,image/jpeg,image/webp"><small>JPG, PNG or WebP, maximum 2 MB.</small></label><div><button class="primary">Save Product</button> <a class="button" href="<?= site_url('products') ?>">Cancel</a></div></form><?= $this->endSection() ?>
